11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	    }
28	    [data-color="red"] { --fg: #dc2626; }
29	    [data-color="green"] { --fg: #16a34a; }
30	    [data-color="amber"] { --fg: #d97706; }
31	    [data-color="violet"] { --fg: #7c3aed; }
32	    [data-color="cyan"] { --fg: #0891b2; }
33	    @media (prefers-color-scheme: dark) {
34	      :root {
35	        --bg: #111;
36	        --text: #d1d5db;
37	        --fg: #93c5fd;
38	        --shadow: rgba(0, 0, 0, 0.6);
39	        --kbd-bg: rgba(255, 255, 255, 0.15);
40	      }
41	      [data-color="red"] { --fg: #fca5a5; }
42	      [data-color="green"] { --fg: #86efac; }
43	      [data-color="amber"] { --fg: #fcd34d; }
44	      [data-color="violet"] { --fg: #c4b5fd; }
45	      [data-color="cyan"] { --fg: #67e8f9; }
46	    }
47	    @media (prefers-contrast: more) {
48	      :root {
49	        --shadow: rgba(0, 0, 0, 0.9);
50	      }
51	      .hint {
52	        opacity: 1;
53	      }
54	    }
55	    @media (forced-colors: active) {
56	      svg circle {
57	        stroke: CanvasText;
58	        stroke-width: 2;
59	      }
60	    }
61	    body {
62	      min-height: 100vh;
63	      min-height: 100dvh;
64	      display: grid;
65	      place-items: center;
66	      padding: 1rem;
67	      background: var(--bg);
68	      color: var(--text);
69	      font-family: system-ui, -apple-system, sans-serif;
70	    }
71	    main {
72	      width: 100%;
73	      display: flex;
74	      flex-direction: column;
75	      align-items: center;
76	      text-align: center;
77	    }
78	    button {
79	      display: block;
80	      width: min(360px, 100%, 60vh);
81	      aspect-ratio: 1;
82	      border: 0;
83	      border-radius: 50%;
84	      background: none;
85	      color: var(--fg);
86	      cursor: pointer;
87	      touch-action: manipulation;
88	      -webkit-tap-highlight-color: transparent;
89	      transition: color 0.4s ease;
90	      contain: layout style paint;
91	      will-change: transform;
92	    }
93	    .no-transition,
94	    .no-transition svg {
95	      transition: none !important;
96	    }
97	    button:focus-visible {
98	      outline: 3px solid currentColor;
99	      outline-offset: 8px;
100	    }
101	    svg {
102	      display: block;
103	      width: 100%;
104	      height: 100%;
105	      overflow: visible;
106	      opacity: 0.85;
107	      filter: drop-shadow(0 8px 16px var(--shadow));
108	      transition: opacity 0.3s ease;
109	      backface-visibility: hidden;
110	    }
111	    button:active svg,
112	    button:focus-visible svg {
113	      opacity: 1;
114	    }
115	    @keyframes pulse {
116	      0% {
117	        filter: drop-shadow(0 8px 16px var(--shadow)) drop-shadow(0 0 20px currentColor);
118	      }
119	      100% {
120	        filter: drop-shadow(0 8px 16px var(--shadow));
121	      }
122	    }
123	    @media (hover: hover) {
124	      button:hover svg {
125	        opacity: 1;
126	      }
127	    }
128	    @media (prefers-reduced-motion: no-preference) {
129	      svg {
130	        transition:
131	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
132	          opacity 0.3s ease;
133	      }
134	      button:focus-visible svg {
135	        transform: scale(1.05);
136	      }
137	      button:active svg {
138	        transform: scale(0.97);
139	      }
140	      button.color-changed svg {
141	        animation: pulse 0.5s ease-out;
142	      }
143	    }
144	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
145	      button:hover:not(:active) svg {
146	        transform: scale(1.05);
147	      }
148	    }
149	    .visually-hidden {
150	      position: absolute;
151	      width: 1px;
152	      height: 1px;
153	      overflow: hidden;
154	      clip-path: inset(50%);
155	      white-space: nowrap;
156	    }
