167	      display: inline-block;
168	      padding: 0.125rem 0.375rem;
169	      background: var(--kbd-bg);
170	      border: 1px solid transparent;
171	      border-radius: 0.25rem;
172	      font-family: monospace;
173	      font-size: 0.75em;
174	    }
175	  </style>
