177	<body>
178	  <main>
179	    <h1 class="visually-hidden">Animated Circle</h1>
180	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
181	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
182	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
183	      </svg>
184	    </button>
185	    <p class="status" id="status" role="status" aria-atomic="true">Blue</p>
186	    <p class="hint" id="hint"><span class="verb">Click</span> to cycle colors • <kbd>Shift</kbd> to reverse • <kbd>Arrows</kbd>/<kbd>Home</kbd>/<kbd>End</kbd> to navigate</p>
187	  </main>
188	  <script>
189	    const button = document.querySelector('button');
190	    const status = document.querySelector('.status');
191	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
192	    const storageKey = 'circle-color';
193	
194	    // Safely retrieve saved color from localStorage, returning null if unavailable
195	    function loadColor() {
196	      try {
197	        return localStorage.getItem(storageKey);
198	      } catch {
199	        return null;
200	      }
201	    }
202	
203	    // Safely save color to localStorage, silently failing if unavailable
204	    function saveColor(color) {
205	      try {
206	        localStorage.setItem(storageKey, color);
207	      } catch {}
208	    }
209	
210	    const savedColor = loadColor();
211	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
212	
213	    // Apply current color to button and update status display
214	    function applyColor() {
215	      const color = colors[index];
216	      if (color === 'blue') {
217	        delete button.dataset.color;
218	      } else {
219	        button.dataset.color = color;
220	      }
221	      status.textContent = color[0].toUpperCase() + color.slice(1);
222	    }
223	
224	    // Cycle color by step amount and trigger pulse animation
225	    function changeColor(step) {
226	      const next = (index + step + colors.length) % colors.length;
227	      // Home/End at the boundary shouldn't pulse or rewrite storage
228	      if (next === index) return;
229	      index = next;
230	      applyColor();
231	      saveColor(colors[index]);
232	
233	      button.classList.remove('color-changed');
234	      void button.offsetWidth;
235	      button.classList.add('color-changed');
236	    }
237	
238	    applyColor();
239	    // Double rAF ensures paint completes before enabling animations
240	    requestAnimationFrame(() => requestAnimationFrame(() => {
241	      button.classList.remove('no-transition');
242	    }));
243	
244	    // Update instructions to show "Tap" on touch devices or "Click" on hover-capable devices
245	    const hoverQuery = matchMedia('(hover: none)');
246	    const verbSpan = document.querySelector('.hint .verb');
247	    function updateVerb() {
248	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
249	    }
250	    updateVerb();
251	    hoverQuery.addEventListener('change', updateVerb);
252	
253	    // Space and Enter activate through the native click, but keyboard-synthesized
254	    // clicks don't reliably carry shiftKey, so remember it from the key events
255	    let shiftHeld = false;
256	    const isActivationKey = (event) => event.key === 'Enter' || event.key === ' ';
257	    button.addEventListener('keyup', (event) => {
258	      if (isActivationKey(event)) shiftHeld = event.shiftKey;
259	    });
260	    button.addEventListener('blur', () => {
261	      shiftHeld = false;
262	    });
263	
264	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
265	    button.addEventListener('keydown', (event) => {
266	      if (isActivationKey(event)) {
267	        shiftHeld = event.shiftKey;
268	        // Holding Enter would otherwise fire a click on every repeat
269	        if (event.repeat && event.key === 'Enter') event.preventDefault();
270	        return;
271	      }
272	      if (event.altKey || event.ctrlKey || event.metaKey) return;
273	      if (event.key in keySteps) {
274	        event.preventDefault();
275	        changeColor(keySteps[event.key]);
276	      } else if (event.key === 'Home') {
277	        event.preventDefault();
278	        changeColor(-index);
279	      } else if (event.key === 'End') {
280	        event.preventDefault();
281	        changeColor(colors.length - 1 - index);
282	      }
283	    });
284	    button.addEventListener('click', (event) => {
285	      changeColor(event.shiftKey || shiftHeld ? -1 : 1);
286	      shiftHeld = false;
287	    });
288	    button.addEventListener('animationend', () => {
289	      button.classList.remove('color-changed');
290	    });
291	    // Sync color across tabs when storage changes
292	    addEventListener('storage', (event) => {
293	      // key is null when another tab calls localStorage.clear()
294	      if (event.key !== storageKey && event.key !== null) return;
295	      const newIndex = colors.indexOf(event.newValue);
296	      index = newIndex === -1 ? 0 : newIndex;
297	      applyColor();
298	    });
299	  </script>
300	</body>
301	</html>
